<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Constancia <?= (int)$pago['id_pago_planilla'] ?></title><style>body{font-family:Arial,sans-serif;background:#eef2ff;color:#172554;margin:0;padding:30px}.hoja{max-width:760px;margin:auto;background:white;border:1px solid #bfdbfe;border-radius:18px;padding:36px;box-shadow:0 15px 45px #1e3a8a22}.cab{display:flex;justify-content:space-between;border-bottom:2px solid #dbeafe;padding-bottom:18px}.titulo{font-size:25px;font-weight:700}.codigo{color:#2563eb;font-weight:700}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:24px 0}.dato{background:#eff6ff;padding:13px;border-radius:10px}.dato small{display:block;color:#64748b;margin-bottom:5px}.monto{text-align:center;background:#dcfce7;color:#166534;border-radius:14px;padding:20px;font-size:30px;font-weight:700}.pie{margin-top:30px;display:flex;justify-content:space-between;color:#64748b;font-size:12px}.acciones{max-width:760px;margin:15px auto;text-align:right}.acciones button,.acciones a{border:0;border-radius:10px;padding:10px 16px;text-decoration:none;font-weight:700}.acciones button{background:#2563eb;color:white}.acciones a{background:white;color:#334155}@media print{body{background:white;padding:0}.hoja{box-shadow:none;border:0}.acciones{display:none}}</style></head><body><div class="acciones"><a href="javascript:history.back()">Volver</a> <button onclick="window.print()">Imprimir</button></div><main class="hoja"><div class="cab"><div><div class="titulo"><?= htmlspecialchars($institucion['nombre']) ?></div><div><?= htmlspecialchars($institucion['ruc']??'') ?></div><small><?= htmlspecialchars($institucion['direccion']??'') ?></small></div><div class="codigo">CONSTANCIA PL-<?= date('Y',strtotime($pago['pagado_en'])) ?>-<?= str_pad((string)$pago['id_pago_planilla'],6,'0',STR_PAD_LEFT) ?></div></div><h1>Constancia de pago de Planilla</h1><div class="grid"><div class="dato"><small>Trabajador</small><b><?= htmlspecialchars($pago['trabajador']) ?></b></div><div class="dato"><small>Código / documento</small><b><?= htmlspecialchars(($pago['codigo_trabajador']?:'—').' · '.($pago['documento_numero']?:'—')) ?></b></div><div class="dato"><small>Cargo</small><b><?= htmlspecialchars($pago['cargo']?:'No especificado') ?></b></div><div class="dato"><small>Período</small><b><?= htmlspecialchars($pago['periodo']) ?></b></div><div class="dato"><small>Medio y referencia</small><b><?= htmlspecialchars($pago['medio_pago'].' · '.($pago['referencia']?:'Sin referencia')) ?></b></div><div class="dato"><small>Fecha de pago</small><b><?= htmlspecialchars($pago['pagado_en']) ?></b></div></div><div class="monto">S/ <?= number_format((float)$pago['importe'],2) ?></div><div class="grid"><div class="dato"><small>Total neto del período</small><b>S/ <?= number_format((float)$pago['monto_pagar'],2) ?></b></div><div class="dato"><small>Saldo pendiente actual</small><b>S/ <?= number_format((float)$pago['saldo_pendiente'],2) ?></b></div></div><div class="pie"><span>Registrado por <?= htmlspecialchars($pago['responsable']) ?></span><span><?= $pago['estado']==='ANULADO'?'DOCUMENTO ANULADO':'Documento interno de control' ?></span></div></main></body></html>
